## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;
  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd5;

  logic        clk = 1'b0;
  logic        rst = 1'b1;
  logic [7:0]  s_axis_tdata = 8'h00;
  logic        s_axis_tvalid = 1'b0;
  logic [15:0] prescale = PRESCALE;

  wire         s_axis_tready;
  wire         txd;
  wire         busy;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart_tx dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .txd(txd),
    .busy(busy),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1;
    wait_clks(4);
    rst = 1'b0;
    wait_clks(4);
  endtask

  task automatic send_first_and_drop(input logic [7:0] b);
    logic ready;
    s_axis_tdata = b;
    s_axis_tvalid = 1'b1;
    do begin
      ready = s_axis_tready;
      @(negedge clk);
    end while (!ready);
    s_axis_tvalid = 1'b0;
    s_axis_tdata = 8'h00;
  endtask

  initial begin
    do_reset();

    // Start one normal frame, then deassert tvalid before the data bits.
    send_first_and_drop(8'hA5);

    // Enter the first data-bit interval and raise tvalid with 8'h3C.
    wait_clks(6);
    s_axis_tdata = 8'h3C;
    s_axis_tvalid = 1'b1;

    // Hold the mid-frame transaction until it is loaded and the following
    // frame has had time to shift out.  Finish while still asserted to avoid
    // dropping tvalid while tready is low.
    wait_clks(2000);

    $display("T11: txd=%b busy=%b", txd, busy);
    $finish;
  end

endmodule
```

